 "content": "def transform(grid):
    """Stamp the encoded ordered color run at each matching isolated marker."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    # Ordered motifs are contiguous nonzero runs at the top/bottom edges.
    motifs = []
    for r in {0, h - 1}:
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            seq = []
            while c < w and grid[r][c] != 0:
                seq.append(grid[r][c])
                c += 1
            motifs.append((r, start, seq))

    # Any non-edge-run nonzero cell is a marker. Match its color to a motif,
    # then align that color's motif position exactly on the marker.
    edge_cells = {(r, c) for r, start, seq in motifs for c in range(start, start + len(seq))}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in edge_cells:
                continue
            match = next(((start, seq) for _, start, seq in motifs if color in seq), None)
            if match is None:
                continue
            _, seq = match
            idx = seq.index(color)
            left = c - idx
            for j, value in enumerate(seq):
                dest = left + j
                if 0 <= dest < w:
                    out[r][dest] = value
    return out


